<?php declare(strict_types=1); ?>
<section class="page-intro"><div class="item-hero"><img class="item-thumb lg" src="/item-image.php?item=<?=rawurlencode((string)$market['item'])?>&size=96" alt=""><div><span class="kicker">MARKTVARIANT</span><h1><?=h($market['item'])?></h1><p><?=$market['requirement']!==null?'q'.(int)$market['requirement'].' ':''?><?=h($market['attribute_name'])?><?=(int)$market['is_oldschool']?' · OS':''?><?=(int)$market['is_inscribable']?' · insc':''?></p><code><?=h($market['market_key'])?></code></div></div><a class="btn secondary" href="/markets">← Markten</a></section>
<div class="statgrid"><div class="stat"><span>Actieve samples</span><b><?=(int)$market['samples']?></b></div><div class="stat"><span>WTB</span><b><?=(int)$market['buys']?></b></div><div class="stat"><span>WTS</span><b><?=(int)$market['sells']?></b></div><div class="stat"><span>Mediaan WTB per stuk</span><b><?=h($currency->formatDual($analytics['buy_median']))?></b></div><div class="stat"><span>Mediaan WTS per stuk</span><b><?=h($currency->formatDual($analytics['sell_median']))?></b></div><div class="stat"><span>Spread</span><b><?=h($currency->formatDual($analytics['spread']))?></b></div></div>
<section class="panel"><h2>Prijsinterpretatie</h2><p class="muted">Alle marktprijzen hierboven zijn per item. Een advertentie met <code>stk</code> of <code>stack</code> wordt als 250 stuks behandeld. Armbrace-equivalent gebruikt de ingestelde koers van <?=number_format($currency->ectoPerArmbrace(),2,',','.')?> ecto per armbrace.</p></section>
<section class="panel"><h2>Marktkwaliteit</h2><div class="statgrid"><div class="stat"><span>Totaalscore</span><b><?=(int)($market['quality']['score']??0)?>/100</b></div><div class="stat"><span>Datakwaliteit</span><b><?=h($market['quality']['data_quality']??'—')?></b></div><div class="stat"><span>Liquiditeit</span><b><?=h($market['quality']['liquidity']??'—')?></b></div><div class="stat"><span>Prijszekerheid</span><b><?=h($market['quality']['price_certainty']??'—')?></b></div></div></section>
<section class="panel"><h2>Prijsdata</h2><p class="muted"><?=(int)$analytics['unique_traders']?> unieke traders · <?=(int)$analytics['buy_count']?> WTB · <?=(int)$analytics['sell_count']?> WTS</p><div id="structuredChart" class="pricechart"></div></section>
<section class="panel"><h2>Recente advertenties</h2><div class="tablewrap"><table><thead><tr><th>Type</th><th>Originele prijs</th><th>Prijs per stuk</th><th>Speler</th><th>Status</th><th>Segment</th></tr></thead><tbody><?php foreach($offers as$o):?><tr><td><span class="badge <?=h($o['trade_type'])?>"><?=strtoupper(h($o['trade_type']))?></span></td><td><?=$o['price_amount']!==null?h($o['price_amount'].$o['price_currency']):'—'?><div class="muted"><?=h($o['price_basis']??'unknown')?><?=$o['quantity']!==null?' · aantal '.h($o['quantity']):''?></div></td><td><?=h($currency->formatDual($o['unit_price_ecto']!==null?(float)$o['unit_price_ecto']:null))?></td><td><?=h($o['player'])?><div class="muted"><?=h(lw_local_datetime($o['posted_at']))?></div></td><td><span class="badge"><?=h($o['lifecycle_status'])?></span></td><td><code><?=h($o['raw_segment'])?></code></td></tr><?php endforeach;?></tbody></table></div></section>
<script>(()=>{const p=<?=json_encode($analytics['points'],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>,t=document.getElementById('structuredChart');if(!p.length){t.innerHTML='<div class="emptychart">Nog geen prijsdata.</div>';return}const w=1100,h=300,pd={l:60,r:20,t:20,b:35},v=p.map(x=>+x.price),mn=Math.min(...v),mx=Math.max(...v),lo=mn===mx?Math.max(0,mn-1):mn,hi=mn===mx?mx+1:mx,x=i=>pd.l+(p.length===1?(w-pd.l-pd.r)/2:i*(w-pd.l-pd.r)/(p.length-1)),y=n=>pd.t+(hi-n)*(h-pd.t-pd.b)/(hi-lo);let s=`<svg viewBox="0 0 ${w} ${h}">`;for(let i=0;i<5;i++){const yy=pd.t+i*(h-pd.t-pd.b)/4,n=hi-(hi-lo)*i/4;s+=`<line x1="${pd.l}" y1="${yy}" x2="${w-pd.r}" y2="${yy}" class="gridline"/><text x="${pd.l-8}" y="${yy+4}" text-anchor="end" class="axislabel">${n.toFixed(1)}e</text>`}p.forEach((a,i)=>s+=`<circle cx="${x(i)}" cy="${y(+a.price)}" r="5" class="chartpoint ${a.type}-point"><title>${a.type} ${a.price}e · ${a.player}</title></circle>`);t.innerHTML=s+'</svg>'})();</script>
